p='minidb/cli.py'
s=open(p).read()
i=s.index('def format_value')
head=s[:i]
body='''def format_value(value: Value) -> str:
    """Render one cell: None -> 'NULL', True -> 'TRUE', False -> 'FALSE',
    anything else -> ``str(value)``."""
    if value is None:
        return "NULL"
    if value is True:
        return "TRUE"
    if value is False:
        return "FALSE"
    return str(value)


def format_result(result: QueryResult) -> str:
    """Render a QueryResult as text (no trailing newline).

    If ``result.columns`` is non-empty: a header line, a separator line of
    dashes, then one line per row, then ``'(N rows)'`` (``'(1 row)'`` for 1).
    If ``result.columns`` is empty: ``'OK (N rows affected)'``.
    """
    if not result.columns:
        return f"OK ({result.row_count} rows affected)"
    cells = [[format_value(v) for v in row] for row in result.rows]
    widths = [len(c) for c in result.columns]
    for row in cells:
        for i, cell in enumerate(row):
            if i < len(widths):
                widths[i] = max(widths[i], len(cell))

    def _line(items: list[str]) -> str:
        return " | ".join(item.ljust(widths[i]) for i, item in enumerate(items))

    lines = [_line(list(result.columns)), _line(["-" * w for w in widths])]
    lines.extend(_line(row) for row in cells)
    count = len(result.rows)
    lines.append("(1 row)" if count == 1 else f"({count} rows)")
    return "\\n".join(lines)


def _run_statement(engine: Engine, sql: str, stdout: TextIO, stderr: TextIO) -> None:
    try:
        result = engine.execute(sql)
    except MiniDBError as error:
        stderr.write(f"ERROR: {error}\\n")
        return
    stdout.write(format_result(result) + "\\n")


def run_repl(
    stdin: TextIO,
    stdout: TextIO,
    stderr: TextIO,
    engine: Optional[Engine] = None,
) -> int:
    """Read SQL from ``stdin`` line by line and execute it.

    Returns 0.
    """
    if engine is None:
        engine = Engine()
    buffer = ""
    for line in stdin:
        if line.strip() == ".exit":
            return 0
        buffer = buffer + line if buffer else line
        stripped = buffer.strip()
        if stripped.endswith(";"):
            _run_statement(engine, stripped, stdout, stderr)
            buffer = ""
    if buffer.strip():
        _run_statement(engine, buffer.strip(), stdout, stderr)
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    """CLI entry point: run the REPL on sys.stdin/stdout/stderr and return
    its exit code. ``argv`` is accepted for future options and ignored."""
    return run_repl(sys.stdin, sys.stdout, sys.stderr)


if __name__ == "__main__":
    sys.exit(main())
'''
open(p,'w').write(head+body)
t='tests/test_cli.py'
